// SECTION: WEB UI SERVER & SSE STREAMING (from web.go)
// ============================================================================
var registerWebOnce sync.Once

// RegisterWebRoutes registers Web UI and SSE testing endpoints on http.DefaultServeMux.
func RegisterWebRoutes(cfg Config) {
	registerWebOnce.Do(func() {
		http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != "/" {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(indexHTML)
		})

		http.HandleFunc("/api/test", func(w http.ResponseWriter, r *http.Request) {
			if r.Method != http.MethodGet {
				http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
				return
			}
			w.Header().Set("Content-Type", "text/event-stream")
			w.Header().Set("Cache-Control", "no-cache")
			w.Header().Set("Connection", "keep-alive")

			flusher, ok := w.(http.Flusher)
			if !ok {
				http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
				return
			}

			reqCfg := cfg
			q := r.URL.Query()
			if m := q.Get("max"); m != "" {
				reqCfg.MaxScan, _ = strconv.Atoi(m)
			}
			if p := q.Get("port"); p != "" {
				reqCfg.Port, _ = strconv.Atoi(p)
			}
			if dn := q.Get("dn"); dn != "" {
				reqCfg.DownloadNum, _ = strconv.Atoi(dn)
			}
			if t := q.Get("topn"); t != "" {
				reqCfg.TopN, _ = strconv.Atoi(t)
			}
			if d := q.Get("dlc"); d != "" {
				reqCfg.DLConc, _ = strconv.Atoi(d)
			}
			if dt := q.Get("dt"); dt != "" {
				reqCfg.Duration, _ = strconv.Atoi(dt)
			}
			if u := q.Get("url"); u != "" {
				reqCfg.URL = u
			}
			if qd := q.Get("qd"); qd != "" {
				reqCfg.QuickDuration, _ = strconv.Atoi(qd)
			}
			if s := q.Get("skip429"); s != "" {
				reqCfg.Skip429 = (s == "true")
			}
			if f := q.Get("filter"); f != "" {
				reqCfg.FilterMode = f
			}
			if s := q.Get("sni"); s != "" {
				reqCfg.SNI = s
			}

			var sendMu sync.Mutex
			sendEvent := func(evtType string, data interface{}) {
				sendMu.Lock()
				defer sendMu.Unlock()
				b, _ := json.Marshal(data)
				fmt.Fprintf(w, "event: %s\ndata: ", evtType)
				w.Write(b)
				fmt.Fprint(w, "\n\n")
				flusher.Flush()
			}

			sendEvent("status", "Generating IPs...")
			ips := GenerateIPs(reqCfg.MaxScan, reqCfg.Unique, reqCfg.IPFile)

			sendEvent("status", fmt.Sprintf("Scanning %d IPs (TCP + HTTPS anti-403 check)...", len(ips)))
			validNodes := ScanRoutesWithProfile(r.Context(), ips, reqCfg.Port, reqCfg.ScanConcurrent, reqCfg.GetProbeProfile(), func(done, total, valid int) {
				if done%10 == 0 || done == total {
					sendEvent("progress_scan", map[string]int{"done": done, "total": total, "valid": valid})
				}
			})

			if len(validNodes) == 0 {
				sendEvent("error", "No valid IPs found.")
				return
			}

			sort.Slice(validNodes, func(i, j int) bool {
				return validNodes[i].TCPLatency < validNodes[j].TCPLatency
			})
			candidates := validNodes

			if isCustomURL(reqCfg.URL) {
				reqCfg.SkipLoadLatency = true
				reqCfg.StopThreshold = 9999.0 // disable fast-exit
				if reqCfg.FilterMode == "multi-colo" {
					sendEvent("status", "Multi-Colo filtering not supported in custom URL mode. Falling back to speed pre-filter...")
					reqCfg.FilterMode = "speed"
				}
			}

			switch reqCfg.FilterMode {
			case "speed":
				// Cap pre-filter pool to TopN*2 (sorted by latency), boost concurrency.
				quickPool := candidates
				maxPool := reqCfg.TopN * 2
				if len(quickPool) > maxPool {
					quickPool = quickPool[:maxPool]
				}
				quickCfg := reqCfg
				quickCfg.DLConc = reqCfg.DLConc * 3
				if quickCfg.DLConc < 6 {
					quickCfg.DLConc = 6
				}

				sendEvent("status", fmt.Sprintf("Speed Pre-filter: running quick test (%ds) on %d candidates (%d workers)...",
					reqCfg.QuickDuration, len(quickPool), quickCfg.DLConc))
				candidates = runQuickFilter(r.Context(), quickPool, quickCfg, reqCfg.TopN, func(done, total int) {
					sendEvent("progress_colo", map[string]int{"done": done, "total": total})
				})

			case "multi-colo":
				if len(candidates) > reqCfg.TopN {
					candidates = candidates[:reqCfg.TopN]
				}

				sendEvent("status", fmt.Sprintf("Detecting Colo for %d candidates...", len(candidates)))
				_, coloGroups := detectColoBatch(r.Context(), candidates, reqCfg.Port, reqCfg.ScanConcurrent, func(done, total int) {
					sendEvent("progress_colo", map[string]int{"done": done, "total": total})
				})

				if len(coloGroups) > 0 {
					type coloStat struct {
						name  string
						count int
						avgMs float64
					}
					var stats []coloStat
					for colo, nodes := range coloGroups {
						stats = append(stats, coloStat{colo, len(nodes), avgLatency(nodes)})
					}
					sort.Slice(stats, func(i, j int) bool { return stats[i].avgMs < stats[j].avgMs })

					var multiColoCandidates []NodeResult
					numColos := 3
					if len(stats) < numColos {
						numColos = len(stats)
					}
					for i := 0; i < numColos; i++ {
						multiColoCandidates = append(multiColoCandidates, coloGroups[stats[i].name]...)
					}
					candidates = multiColoCandidates
					sendEvent("status", fmt.Sprintf("Selected top %d Colos (candidates: %d) — running download test...", numColos, len(candidates)))
				} else {
					sendEvent("status", "No valid Colo detected, testing all candidates...")
				}

			default: // "none"
				if len(candidates) > reqCfg.TopN {
					candidates = candidates[:reqCfg.TopN]
				}
				sendEvent("status", fmt.Sprintf("Skipping candidate filtering, testing top %d candidates directly...", len(candidates)))
			}

			if len(candidates) == 0 {
				sendEvent("error", "No candidates selected for testing.")
				return
			}

			results := runParallelDownloadTest(r.Context(), candidates, reqCfg, func(res NodeResult) {
				if res.Colo != "429" || !reqCfg.Skip429 {
					sendEvent("progress_download", res)
				}
			}, func(msg string) {
				sendEvent("status", msg)
			}, func(p LiveProgress) {
				sendEvent("progress_live", p)
			}, func() {
				sendEvent("fast_exit", "Speed threshold reached, stopping early.")
			})

			if len(results) == 0 {
				sendEvent("error", "All tested IPs failed or were rate-limited. Please wait and retry.")
				return
			}

			for i, res := range results {
				tier := TierCandidate
				if i == 0 {
					tier = TierActive
				} else if i <= 2 {
					tier = TierStandby
				}
				rm := FromNodeResult(res, tier)
				GlobalRouteStore.UpsertRoute(*rm)
			}

			sendEvent("status", "Test Complete")
			sendEvent("complete", results)
		})
	})
}

func RunWeb(cfg Config) {
	RegisterWebRoutes(cfg)
	fmt.Printf("🚀 Web UI started. Open http://localhost%s in your browser\n", cfg.WebPort)
	if err := http.ListenAndServe(cfg.WebPort, nil); err != nil {
		fmt.Printf("Web server error: %v\n", err)
	}
}

// ============================================================================
// SECTION: MAIN ENTRYPOINT & CLI PARSING (from main.go)
// ============================================================================
func main() {
	cfg := DefaultConfig()

	flag.IntVar(&cfg.Port, "p", cfg.Port, "Target port")
	flag.IntVar(&cfg.MaxScan, "max", cfg.MaxScan, "Max IPs to scan")
	flag.IntVar(&cfg.TopN, "topn", cfg.TopN, "Top N candidates by latency for speed test")
	flag.IntVar(&cfg.DLConc, "dlc", cfg.DLConc, "Parallel download test concurrency")
	flag.IntVar(&cfg.DownloadNum, "dn", cfg.DownloadNum, "Download test count")
	flag.IntVar(&cfg.Duration, "dt", cfg.Duration, "Download duration (seconds)")
	flag.Float64Var(&cfg.StopThreshold, "st", cfg.StopThreshold, "Stop threshold MB/s (CF URL mode only)")
	flag.BoolVar(&cfg.Unique, "u", cfg.Unique, "Unique C-subnet")
	flag.StringVar(&cfg.IPFile, "f", cfg.IPFile, "Custom IP file")
	flag.StringVar(&cfg.Output, "o", cfg.Output, "Output file")
	flag.IntVar(&cfg.ScanConcurrent, "sc", cfg.ScanConcurrent, "Scan concurrency")
	flag.BoolVar(&cfg.Skip429, "skip429", cfg.Skip429, "Discard 429 rate-limited IPs silently")
	flag.StringVar(&cfg.URL, "url", cfg.URL, "Custom download test URL")
	flag.IntVar(&cfg.QuickDuration, "qd", cfg.QuickDuration, "Quick pre-filter duration in seconds (custom URL mode)")
	flag.StringVar(&cfg.FilterMode, "filter", cfg.FilterMode, "Candidate filter mode (speed, multi-colo, none)")
	flag.StringVar(&cfg.SNI, "sni", cfg.SNI, "Custom TLS SNI (ServerName)")
	flag.StringVar(&cfg.WSSHost, "wsshost", cfg.WSSHost, "WebSocket fake Host for goway handshake check (enabled by default, pass empty string to disable)")
	flag.StringVar(&cfg.WSSPath, "wsspath", cfg.WSSPath, "WebSocket Path for goway handshake check (default /pyway)")
	flag.StringVar(&cfg.Profile, "profile", cfg.Profile, "Probe profile: CFST (default), GOWAY-WSS, CUSTOM")
	flag.BoolVar(&cfg.DaemonMode, "daemon", cfg.DaemonMode, "Run as continuous Route Quality Probe daemon")
	flag.StringVar(&cfg.APIAddr, "api-addr", cfg.APIAddr, "Local API listen address (default 127.0.0.1:9876)")
	flag.IntVar(&cfg.ActiveInterval, "active-interval", cfg.ActiveInterval, "Active route probe interval in seconds")
	flag.IntVar(&cfg.StandbyInterval, "standby-interval", cfg.StandbyInterval, "Standby route probe interval in seconds")
	flag.IntVar(&cfg.CandidateInterval, "candidate-interval", cfg.CandidateInterval, "Candidate route probe interval in seconds")
	flag.IntVar(&cfg.FailedInterval, "failed-interval", cfg.FailedInterval, "Failed route recovery probe interval in seconds")
	flag.StringVar(&cfg.ScoreMode, "mode", cfg.ScoreMode, "Scoring mode: normal or peak")
	flag.StringVar(&cfg.StateFile, "state", cfg.StateFile, "State persistence JSON file path")
	flag.BoolVar(&cfg.DiscoveryEnabled, "discovery", cfg.DiscoveryEnabled, "Enable continuous Cloudflare IP discovery in daemon mode")
	flag.IntVar(&cfg.DiscoveryInterval, "discovery-interval", cfg.DiscoveryInterval, "Discovery scan interval in seconds (default 3600)")
	flag.IntVar(&cfg.DiscoveryScanCount, "discovery-count", cfg.DiscoveryScanCount, "Discovery IPs to scan per pass (default 200)")
	versionFlag := flag.Bool("v", false, "Show version and exit")
	flag.BoolVar(versionFlag, "version", false, "Show version and exit")

	webMode := false
	webPort := "9876"
	if len(os.Args) > 0 {
		var newArgs []string
		newArgs = append(newArgs, os.Args[0])
		for i := 1; i < len(os.Args); i++ {
			if os.Args[i] == "-web" {
				webMode = true
				if i+1 < len(os.Args) && !strings.HasPrefix(os.Args[i+1], "-") {
					webPort = os.Args[i+1]
					i++
				}
			} else {
				newArgs = append(newArgs, os.Args[i])
			}
		}
		os.Args = newArgs
	}

	flag.Bool("web", false, "Start Web UI server (-web <port>)")
	flag.Parse()

	if *versionFlag {
		println("CFST v2.4.0 (GOWAY Route Quality Probe & Long-Term Stability Analyzer)")
		return
	}

	if cfg.DaemonMode {
		RunDaemon(cfg)
	} else if webMode {
		cfg.WebMode = true
		cfg.WebPort = webPort
		if !strings.Contains(cfg.WebPort, ":") {
			cfg.WebPort = ":" + cfg.WebPort
		}
		RunWeb(cfg)
	} else {
		RunCLI(cfg)
	}
}
